// Checks the job (trust boundary), looks the programs up in pc_tools and builds the run state.
const cfg = $('Config').first().json;
const job = $('Webhook').first().json.body ?? {};
const AREA_IDS = ['anfragen', 'angebote', 'auftraege', 'rechnungen', 'postfach', 'daten', 'erinnern', 'orga'];
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

const fehler = [];
if (!UUID.test(String(job.jobId ?? ''))) fehler.push('jobId');
if (!Array.isArray(job.programme) || job.programme.length > 8 || !job.programme.every((p) => typeof p === 'string' && p.trim() && p.length <= 80)) fehler.push('programme');
if (!Array.isArray(job.bereiche) || !job.bereiche.length || !job.bereiche.every((b) => AREA_IDS.includes(b))) fehler.push('bereiche');
if (!AREA_IDS.includes(job.nervt)) fehler.push('nervt');
if (!job.stunden || typeof job.stunden !== 'object' || Array.isArray(job.stunden)
  || !Object.entries(job.stunden).every(([k, v]) => AREA_IDS.includes(k) && typeof v === 'number' && v >= 0 && v <= 10)) fehler.push('stunden');
if (job.website !== undefined && !(typeof job.website === 'string' && job.website.length <= 200 && /^https?:\/\/[^\s<>"]+$/i.test(job.website))) fehler.push('website');
if (typeof job.frischeRecherche !== 'boolean') fehler.push('frischeRecherche');
if (fehler.length) throw new Error(`Job ungültig: ${fehler.join(', ')}`); // field names only, no visitor data

const norm = (s) => String(s).trim().toLowerCase().replace(/\s+/g, ' ');
const KEIN_PROGRAMM = new Set(['papier und zettel']); // the chip names no program, nothing to research
const rows = $input.all().map((i) => i.json).filter((r) => r && typeof r.key === 'string' && r.key);
const ausZeile = (r) => ({
  name: r.name || '', aliases: pj(r.aliases, []), vendorUrl: r.vendorUrl || '', gefunden: r.gefunden === true,
  bordmittel: pj(r.bordmittel, []), api: pj(r.api, {}), webhooks: r.webhooks || '', export: r.export || '',
  n8n: r.n8n || 'unbekannt', grenzen: r.grenzen || '', quellen: pj(r.quellen, []), confidence: r.confidence || 'niedrig',
});
const maxAlter = cfg.caps.libraryMaxAlterTage * 864e5;
const library = {};
const unbekannt = [];
const gesehen = new Set();
for (const p of job.programme) {
  const k = norm(p);
  if (gesehen.has(k) || KEIN_PROGRAMM.has(k)) continue;
  gesehen.add(k);
  const r = rows.find((x) => norm(x.key) === k || pj(x.aliases, []).some((a) => norm(a) === k));
  if (r) library[p] = ausZeile(r); // a stale entry still serves when it is not researched again
  const alter = r ? Date.now() - new Date(r.researchedAt).getTime() : Infinity;
  if (!r || (r.reviewed !== true && !(alter <= maxAlter))) {
    unbekannt.push({ programm: p, rowKey: r ? r.key : k, alteAliases: r ? pj(r.aliases, []) : [] });
  }
}
const capsGetroffen = [];
let queue = [];
if (job.frischeRecherche) {
  queue = unbekannt.slice(0, cfg.caps.frischeProgrammeProLead);
  if (unbekannt.length > queue.length) capsGetroffen.push('programme');
}

// Same order as the website's schrittOrder (fallback.ts): mergeResearch matches steps by bereich.
const h = (id) => job.stunden[id] || 0;
const rest = AREA_IDS.filter((id) => job.bereiche.includes(id) && id !== job.nervt && h(id) > 0).sort((x, y) => h(y) - h(x));
const reihenfolge = [job.nervt, ...rest].slice(0, 3).map((bereich, i) => ({ rang: ['Zuerst', 'Danach', 'Später'][i], bereich }));

return [{ json: {
  _zustand: true, jobId: job.jobId, job, kostenUsd: 0, capsGetroffen, erlaubte: [], library, queue, aktuell: null,
  reihenfolge, heute: DateTime.now().setZone('Europe/Berlin').toFormat('dd.MM.yyyy'), websiteFindings: null,
} }];

