  e.vendorUrl = gut(e.vendorUrl) ? e.vendorUrl : '';
  e.gefunden = e.gefunden === true;
  e.aliases = uniq([...(Array.isArray(e.aliases) ? e.aliases : []), ...a.alteAliases, a.programm].filter((x) => typeof x === 'string' && x.trim()));
  S.row = {
    key: a.rowKey, aliases: JSON.stringify(e.aliases), name: String(e.name || a.programm), vendorUrl: e.vendorUrl,
    gefunden: e.gefunden, bordmittel: JSON.stringify(e.bordmittel), api: JSON.stringify(e.api),
