    grenzen: String(e.grenzen || ''), quellen: JSON.stringify(e.quellen), confidence: String(e.confidence || 'niedrig'),
  };
  S.library[a.programm] = { name: S.row.name, aliases: e.aliases, vendorUrl: e.vendorUrl, gefunden: e.gefunden,
    bordmittel: e.bordmittel, api: e.api, webhooks: S.row.webhooks, export: S.row.export, n8n: S.row.n8n,
    grenzen: S.row.grenzen, quellen: e.quellen, confidence: S.row.confidence };
}
S.aktuell = null;
return [{ json: S }];

