// Parses {pdf, dossier}, adds the run data the model can't know, builds the deliver payload.
const cfg = $('Config').first().json;
const S = $('Synthese vorbereiten').first().json;
const res = $input.first().json;
S.kostenUsd += kostenVon(res.usage, cfg.preise);
const capsGetroffen = uniq(S.capsGetroffen);
const fallback = (grund) => ({ jobId: S.jobId, fallback: true, grund, erlaubteQuellen: [] });
let payload;
if (res.error || !Array.isArray(res.content)) payload = fallback('Synthese: HTTP-Fehler');
else if (res.stop_reason !== 'end_turn') payload = fallback(`Synthese: ${res.stop_reason}`);
else {
  const out = pj(letzterText(res.content), null);
  if (!out || typeof out !== 'object' || !out.pdf || !out.dossier) payload = fallback('Synthese: JSON ungültig');
  else {
    const dossier = { ...out.dossier, kostenUsd: rund(S.kostenUsd), capsGetroffen };
    if (Array.isArray(dossier.fragen) && dossier.fragen.length > 5) dossier.fragen = dossier.fragen.slice(0, 5);
    payload = { jobId: S.jobId, fallback: false, erlaubteQuellen: S.erlaubteQuellen, pdf: out.pdf, dossier };
  }
}
return [{ json: { jobId: S.jobId, kostenUsd: rund(S.kostenUsd), capsGetroffen, payload } }];
